const jsonData = pm.response.json();
const expectedCurrency =
    pm.iterationData.get("base_currency") ||
    pm.environment.get("base_currency");

pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Response contains result", function () {
    pm.expect(jsonData).to.have.property("result");
});

pm.test("Response contains rates", function () {
    pm.expect(jsonData).to.have.property("rates");
});

pm.test("API result is success", function () {
    pm.expect(jsonData.result).to.eql("success");
});

pm.test("Base currency matches selected environment", function () {
    pm.expect(jsonData.base_code).to.eql(expectedCurrency);
});

pm.test("Base currency rate is equal to 1", function () {
    pm.expect(jsonData.rates[expectedCurrency]).to.eql(1);
});

pm.test("Currency rates are positive numbers", function () {
    const rates = jsonData.rates;

    pm.expect(rates).to.be.an("object");
    pm.expect(rates).to.have.property("EUR");
    pm.expect(rates).to.have.property("GBP");
    pm.expect(rates).to.have.property("EGP");

    pm.expect(rates.EUR).to.be.a("number").and.above(0);
    pm.expect(rates.GBP).to.be.a("number").and.above(0);
    pm.expect(rates.EGP).to.be.a("number").and.above(0);
});
